const item = items[0];
const INITIAL = new Date('2025-10-17T22:30:00.000Z').getTime();
const marker = Math.floor((Date.now() - INITIAL) / (1000*60*60));
const base = item.json.nof1BaseUrl || 'https://nof1.ai/api';
item.json.accountTotalsUrl = `${base}/account-totals?lastHourlyMarker=${marker}`;
item.json.binanceBaseUrl = item.json.testnet ? 'https://testnet.binancefuture.com' : 'https://fapi.binance.com';
return items;

const data = items[0].json;
const state = this.getWorkflowStaticData('global');
state.lastPositions = state.lastPositions || {};
state.lastOids = state.lastOids || {};
const agentId = data.agentId;
const entries = (data.accountTotals || []).filter(a => a.model_id === agentId);
if (entries.length === 0) {
  return [];
}
// Selecciona el último por since_inception_hourly_marker
entries.sort((a,b) => (b.since_inception_hourly_marker || 0) - (a.since_inception_hourly_marker || 0));
const latest = entries[0];
const currentPositions = latest.positions || {};
const previousPositions = state.lastPositions[agentId] || {};
// Actualiza estado con posiciones actuales
state.lastPositions[agentId] = currentPositions;

// Tabla de OIDs ejecutados para evitar duplicados
const agentOids = state.lastOids[agentId] || (state.lastOids[agentId] = {});

function withinTolerance(entry, current, tolerance) {
  if (!entry || !current || entry <= 0) return true;
  const diff = Math.abs((current - entry) / entry) * 100;
  return diff <= tolerance;
}

const priceTolerance = Number(data.priceTolerance) || 1;

const symbols = Array.from(new Set([
  ...Object.keys(previousPositions),
  ...Object.keys(currentPositions)
]));
const plans = [];
for (const sym of symbols) {
  const prev = previousPositions[sym];
  const curr = currentPositions[sym];
  const prevQty = prev ? Math.abs(prev.quantity || 0) : 0;
  const currQty = curr ? Math.abs(curr.quantity || 0) : 0;

  // ENTER: nueva posición (deduplicación por OID)
  if (!prev && curr && currQty > 0) {
    const oid = curr.entry_oid;
    // Si ya ejecutamos esta OID para este símbolo, saltar
    if (oid && agentOids[sym] === oid) {
      continue;
    }
    plans.push({
      action: 'ENTER',
      symbol: sym,
      side: (curr.quantity || 0) > 0 ? 'BUY' : 'SELL',
      type: 'MARKET',
      quantity: currQty,
      leverage: curr.leverage || 1,
      entryPrice: curr.entry_price,
      currentPrice: curr.current_price,
      shouldExecute: withinTolerance(curr.entry_price, curr.current_price, priceTolerance),
      reason: `New position opened by ${agentId} (OID: ${curr.entry_oid})`,
      entry_oid: curr.entry_oid
    });
  } else if (prev && (!curr || currQty === 0) && prevQty > 0) {
    // EXIT: posición cerrada
    plans.push({
      action: 'EXIT',
      symbol: sym,
      side: (prev.quantity || 0) > 0 ? 'SELL' : 'BUY',
      type: 'MARKET',
      quantity: prevQty,
      leverage: prev.leverage || 1,
      exitPrice: curr ? curr.current_price : prev.entry_price,
      shouldExecute: true,
      reason: `Position closed by ${agentId}`
    });
  }
}

const batchSize = Math.max(plans.length, 1);

return plans.map(p => ({ json: {
  ...p,
  agentId,
  priceTolerance,
  batchSize,
  totalMargin: data.totalMargin,
  marginType: data.marginType,
  binanceBaseUrl: data.binanceBaseUrl,
  binanceApiKey: data.binanceApiKey,
  binanceApiSecret: data.binanceApiSecret,
  telegramEnabled: data.telegramEnabled,
  telegramToken: data.telegramToken,
  telegramChatId: data.telegramChatId
} }));

function formatQty(base, qty) {
  switch(base) {
    case 'BTC': return Number(qty).toFixed(3);
    case 'ETH': return Number(qty).toFixed(3);
    case 'BNB': return Number(qty).toFixed(2);
    case 'SOL': return Number(qty).toFixed(2);
    case 'XRP': return Number(qty).toFixed(0);
    case 'DOGE': return Number(qty).toFixed(0);
    default: return Number(qty).toFixed(4);
  }
}
const item = items[0].json;
const ts = Date.now();
const recvWindow = 5000;
const symbolPair = item.symbol;
const base = symbolPair.replace('USDT', '');
const side = item.side;
const type = 'MARKET';
const newOrderRespType = 'RESULT';

// Gestión de capital: si hay totalMargin y currentPrice válidos, ajustar cantidad
const totalMargin = Number(item.totalMargin || 0);
const leverage = Number(item.leverage || 1);
const currentPrice = Number(item.currentPrice || 0);
const batchSize = Number(item.batchSize || 1);
let quantityCalc = Number(item.quantity || 0);
if (totalMargin > 0 && currentPrice > 0 && batchSize > 0) {
  const allocated = totalMargin / batchSize;
  const desiredQty = (allocated * leverage) / currentPrice;
  quantityCalc = desiredQty;
}
const quantity = formatQty(base, quantityCalc);

const queryString = `symbol=${symbolPair}&side=${side}&type=${type}&quantity=${quantity}&newOrderRespType=${newOrderRespType}&timestamp=${ts}&recvWindow=${recvWindow}`;
return [{ json: {
  ...item,
  order: { symbol: symbolPair, side, type, quantity },
  queryString
} }];

const item = items[0].json;
const state = this.getWorkflowStaticData('global');
state.lastOids = state.lastOids || {};
const agentId = item.agentId || 'deepseek-chat-v3.1';
state.lastOids[agentId] = state.lastOids[agentId] || {};
// Marca OID ejecutada sólo para ENTER
if (item.action === 'ENTER' && item.entry_oid) {
  state.lastOids[agentId][item.symbol] = item.entry_oid;
}
return items;
